INSERT INTO `amin_json` VALUES (126, '', '2023-01-06 16:27:28', '', '2023-01-06 16:27:28', NULL, '{\n  \"type\": \"page\",\n  \"title\": \"Hello world\",\n  \"body\": [\n    {\n      \"type\": \"crud\",\n      \"id\": \"u:9202b6f429b3\",\n      \"syncLocation\": false,\n      \"api\": {\n        \"method\": \"get\",\n        \"url\": \"/prod-api/amis/list\"\n      },\n      \"columns\": [\n        {\n          \"label\": \"ID\",\n          \"type\": \"text\",\n          \"name\": \"id\",\n          \"id\": \"u:6a79ee7bc5ab\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"页面名称\",\n          \"name\": \"menuName\",\n          \"id\": \"u:4defa34120ea\",\n          \"placeholder\": \"-\"\n        },\n        {\n          \"label\": \"创建人\",\n          \"type\": \"text\",\n          \"name\": \"createBy\",\n          \"id\": \"u:8603896d67a4\"\n        },\n        {\n          \"label\": \"创建时间\",\n          \"type\": \"date\",\n          \"name\": \"createTime\",\n          \"id\": \"u:f64a0a4857ea\"\n        },\n        {\n          \"label\": \"更新人\",\n          \"type\": \"text\",\n          \"name\": \"updateBy\",\n          \"id\": \"u:ddd613453221\"\n        },\n        {\n          \"label\": \"更新时间\",\n          \"type\": \"date\",\n          \"name\": \"updateTime\",\n          \"id\": \"u:bfdbce05c6bf\"\n        },\n        {\n          \"label\": \"备注\",\n          \"type\": \"text\",\n          \"name\": \"remark\",\n          \"id\": \"u:c6f1ba9dd777\"\n        },\n        {\n          \"type\": \"operation\",\n          \"label\": \"操作\",\n          \"buttons\": [\n            {\n              \"label\": \"编辑\",\n              \"type\": \"button\",\n              \"actionType\": \"dialog\",\n              \"level\": \"link\",\n              \"dialog\": {\n                \"title\": \"编辑\",\n                \"body\": [\n                  {\n                    \"type\": \"form\",\n                    \"api\": \"/prod-api/amis/update?id=$id\",\n                    \"body\": [\n                      {\n                        \"label\": \"备注\",\n                        \"name\": \"remark\",\n                        \"type\": \"input-text\",\n                        \"id\": \"u:b3b82d7635af\"\n                      },\n                      {\n                        \"label\": \"页面数据\",\n                        \"name\": \"json\",\n                        \"type\": \"textarea\",\n                        \"id\": \"u:8e40c72bf5d4\",\n                        \"minRows\": 3,\n                        \"maxRows\": 20\n                      }\n                    ],\n                    \"id\": \"u:bfeaa70a1808\"\n                  }\n                ],\n                \"type\": \"dialog\",\n                \"id\": \"u:840475854a25\"\n              },\n              \"id\": \"u:345eeee13926\"\n            },\n            {\n              \"label\": \"预览\",\n              \"type\": \"button\",\n              \"actionType\": \"dialog\",\n              \"level\": \"link\",\n              \"dialog\": {\n                \"title\": \"查看详情\",\n                \"body\": [\n                  {\n                    \"type\": \"iframe\",\n                    \"id\": \"u:912458dd8f36\",\n                    \"src\": \"/preview/test?amisid=$id\",\n                    \"width\": \"100%\",\n                    \"height\": \"650px\"\n                  }\n                ],\n                \"type\": \"dialog\",\n                \"id\": \"u:e1972ff5c56b\",\n                \"actions\": [\n                ],\n                \"showCloseButton\": true,\n                \"closeOnEsc\": false,\n                \"showErrorMsg\": true,\n                \"showLoading\": true,\n                \"dataMapSwitch\": false,\n                \"size\": \"xl\"\n              },\n              \"id\": \"u:54b132f49d2f\"\n            },\n            {\n              \"type\": \"button\",\n              \"label\": \"删除\",\n      