INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/amis管理/删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"861239891a1e4a6dbaa1537edc23e41b\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"d9bddae4973a44b187eabea25cb7c5f1\",\r\n  \"name\" : \"删除\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1677636194499,\r\n  \"lock\" : null,\r\n  \"createBy\" : \"admin\",\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"list\",\r\n  \"method\" : \"DELETE\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(() => {\r\n    var count = db.select(\" select count(1) as a  from sys_menu where parent_id = #{id} \")\r\n    if (count.a > 0) {\r\n              throw new Exception(\"存在子菜单,不允许删除\")\r\n    }\r\n    count = db.select(\" select count(1) as a  from sys_role_menu where menu_id = #{id} \")\r\n    if (count.a > 0) {\r\n             throw new Exception(\"菜单已分配,不允许删除\")\r\n    }\r\n    db.insert(\" delete from sys_menu where menu_id = #{id}\")\r\n    db.insert(\" delete from amin_json where id = #{id}\")\r\n    return \"ok\"\r\n});');
